package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParseException;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.IntNode;
import com.fasterxml.jackson.databind.node.JsonNodeFactory;
import com.fasterxml.jackson.databind.node.LongNode;
import com.fasterxml.jackson.databind.node.NumericNode;
import com.fasterxml.jackson.databind.node.TextNode;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TreeTraversingParser_getLongValue_TriageGen2Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }

    /**
     * Helper to instantiate TreeTraversingParser using reflection because 
     * currentNumericNode() is protected and depends on internal state.
     */
    private TreeTraversingParser createParser(JsonNode node) throws Exception {
        TreeTraversingParser parser = new TreeTraversingParser(node);
        // We use reflection to inject the node into the private/protected state 
        // if necessary, but since the constructor takes JsonNode, 
        // we rely on the internal pointer being set to that node.
        return parser;
    }

    /**
     * Helper to mock the behavior of currentNumericNode via reflection 
     * to satisfy the requirement of testing the specific logic in getLongValue.
     */
    private void injectCurrentNumericNode(TreeTraversingParser parser, NumericNode node) throws Exception {
        Field field = TreeTraversingParser.class.getDeclaredField("currentNode");
        field.setAccessible(true);
        field.set(parser, node);
    }

    @Test
    public void testGetLongValue_Success_Long() throws Exception {
        long expectedValue = 1234567890123L;
        LongNode longNode = JsonNodeFactory.instance.longNode(expectedValue);
        TreeTraversingParser parser = new TreeTraversingParser(longNode);

        // Injecting node to simulate currentNumericNode() returning the longNode
        injectCurrentNumericNode(parser, longNode);

        long actualValue = parser.getLongValue();
        Assert.assertEquals(expectedValue, actualValue);
    }

    @Test
    public void testGetLongValue_Success_Int() throws Exception {
        int expectedValue = 42;
        IntNode intNode = JsonNodeFactory.instance.numberNode(expectedValue);
        TreeTraversingParser parser = new TreeTraversingParser(intNode);

        injectCurrentNumericNode(parser, intNode);

        long actualValue = parser.getLongValue();
        Assert.assertEquals((long) expectedValue, actualValue);
    }

    @Test
    public void testGetLongValue_Branch_CannotConvertToInt() throws Exception {
        // This test targets the branch: if (!node.canConvertToInt())
        // We use a very large long that cannot fit into an Integer.
        long largeValue = Long.MAX_VALUE;
        LongNode largeNode = JsonNodeFactory.instance.longNode(largeValue);
        TreeTraversingParser parser = new TreeTraversingParser(largeNode);

        injectCurrentNumericNode(parser, largeNode);

        // Even if canConvertToInt is false, the code proceeds to return node.longValue()
        long actualValue = parser.getLongValue();
        Assert.assertEquals(largeValue, actualValue);
    }

    @Test(expected = ClassCastException.class)
    public void testGetLongValue_ThrowsException_NotANumericNode() throws Exception {
        // The method casts currentNumericNode() to (NumericNode)
        // If the current node is a TextNode, it will throw ClassCastException
        TextNode textNode = JsonNodeFactory.instance.textNode("not a number");
        TreeTraversingParser parser = new TreeTraversingParser(textNode);

        // We bypass the protected currentNumericNode() logic by forcing the state
        // via a field if possible, or by relying on the fact that if currentNumericNode() 
        // returns a Non-Numeric node, the cast fails.
        // Since we can't easily mock the protected method without PowerMock, 
        // we simulate the state that causes the cast error.
        Field field = TreeTraversingParser.class.getDeclaredField("currentNode");
        field.setAccessible(true);
        field.set(parser, textNode);

        parser.getLongValue();
    }

    @Test(expected = NullPointerException.class)
    public void testGetLongValue_ThrowsException_NullNode() throws Exception {
        TreeTraversingParser parser = new TreeTraversingParser(JsonNodeFactory.instance.objectNode());

        Field field = TreeTraversingParser.class.getDeclaredField("currentNode");
        field.setAccessible(true);
        field.set(parser, null);

        parser.getLongValue();
    }
}
